package com.greatleyposhley.professy.collaboration;
import com.greatleyposhley.professy.repositories.UserAccountRepository;import com.greatleyposhley.professy.services.JwtService;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api/internal/auth")public class InternalIdentityController {
 private final UserAccountRepository users;private final JwtService jwt;private final JdbcTemplate jdbc;private final String token;
 public InternalIdentityController(UserAccountRepository users,JwtService jwt,JdbcTemplate jdbc,@Value("${app.identity-service-token:}")String token){this.users=users;this.jwt=jwt;this.jdbc=jdbc;this.token=token;}
 private void authorize(String supplied){if(token.length()<32||!MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),Objects.toString(supplied,"").getBytes(StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 @PostMapping("/refresh")public Object refresh(@RequestHeader(value="X-Identity-Service-Token",required=false)String supplied,@RequestBody Map<String,Object> body){authorize(supplied);var user=users.findById(WorkAccess.number(body.get("userId"))).filter(u->Boolean.TRUE.equals(u.getIsActive())&&!u.getPasswordSetupRequired()&&u.getCredentialVersion()==WorkAccess.number(body.get("credentialVersion"))).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));return Map.of("user",user,"token",jwt.generateToken(user));}
 @PostMapping("/revoke")@Transactional public Object revoke(@RequestHeader(value="X-Identity-Service-Token",required=false)String supplied,@RequestBody Map<String,Object> body){authorize(supplied);jdbc.update("UPDATE user_account SET credential_version=credential_version+1 WHERE id=? AND credential_version=?",WorkAccess.number(body.get("userId")),WorkAccess.number(body.get("credentialVersion")));return Map.of("success",true);}
}
